_LIVE = (ConnState.CONNECTING, ConnState.CONNECTED, ConnState.RECONNECTING)




class _GameSessionProvider:
    """Assignment and refresh through the game client's own Game API calls."""

    def __init__(self, client: CrowdyClient, app_id: str) -> None:
        self._client = client
        self._app_id = app_id

    def assign_server(self) -> Assignment:
        try:
            return self._assign_once()
        except CrowdyError:
            # Assignment goes through the API client, so a failure here often means the
            # instance it is pinned to went away; only a move can recover from that.
            if not self._client.rediscover_endpoint(self._app_id):
                raise
            return self._assign_once()

    def _assign_once(self) -> Assignment:
        server = self._client.server_status.server_with_least_clients()
        if (
            not server
            or not server.get("clientPort")
            or not (server.get("ip4") or server.get("ip6"))
        ):
            raise CrowdyReplicationError("no replication server was assigned", code="Rejected")
        return Assignment(
            server.get("ip4") or "", server.get("ip6") or "", int(server["clientPort"])
        )

    def refresh_token(self, current: Assignment | None) -> TokenMaterial:
        # Naming the server the client is on gets the new token installed there, so the
        # connection keeps its socket instead of being placed again.
        server = (
            CurrentServer(ip4=current.ip4, client_port=current.client_port)
            if current is not None and current.ip4 and current.client_port > 0
            else None
        )
        token = self._client.portal.refresh(server)
        self._client.app_token = token
        return token_material(token, current)


class UdpAPI:
    def __init__(self, client: CrowdyClient) -> None:
        self._client = client
        self._connection: ReplicationConnection | None = None
        self._subscriptions: list[Mapping[str, Callable[[Notification], Any]]] = []

    @property
    def connection(self) -> ReplicationConnection | None:
        """The native connection, once :meth:`connect` made one: batches, stats, batch sends."""
        return self._connection

    def connect(
        self, app_token: AppTokenResponse | None = None, **options: Any
    ) -> ConnectionStatus:
        """Assign a replication server and open the socket. Idempotent while connected.

        ``app_token`` is the minted (or refreshed) token for the app; without it the client's
        :attr:`~crowdypy.CrowdyClient.app_token` is used. ``options`` tune the native
        connection (``bundle_window_ms``, ``ring_capacity``, ``manual_pump``, ...).
        """
        if self._connection is not None and self._connection.state in _LIVE:
            return self.connection_status()
        token = app_token or self._client.app_token
        if token is None:
            raise CrowdyReplicationError(
                "connect needs the app token: pass the AppTokenResponse from "
                "portal.mint_app_token, or call client.set_app_token() first",
                code="NotConnected",
            )
        if app_token is not None:
            self._client.set_app_token(app_token)
        if self._connection is None or options:
            if self._connection is not None:
                self._connection.close()
            self._connection = ReplicationConnection(
                _GameSessionProvider(self._client, token.app_id),
                token_material(token),
                app_id=token.app_id,
                subscriptions=self._subscriptions,
                **options,
            )
        else:
            self._connection.set_token(token_material(token))
        self._connection.connect()
        return self.connection_status()

    def disconnect(self) -> bool:
        """Close the socket and release the connection; subscriptions are kept for the next one."""
        connection, self._connection = self._connection, None
        if connection is not None:
            connection.close()
        return True

    def connection_status(self) -> ConnectionStatus:
        connection = self._connection
        if connection is None:
            return ConnectionStatus(False, ConnState.IDLE)
        state = connection.state
        if state not in _LIVE:
            return ConnectionStatus(False, state)
        server = connection.assignment()
        return ConnectionStatus(
            state == ConnState.CONNECTED,
            state,
            server.ip4 or None,
            server.ip6 or None,
            server.client_port or None,
        )

    def flush_sends(self) -> None:
        """Put the pending bundle on the wire now (at the end of a frame)."""
        if self._connection is not None:
            self._connection.flush_sends()

    def wait_for_in_flight_actor_updates(self) -> None:
        """Native sends complete when they return; this only flushes the pending bundle."""
        self.flush_sends()

    def subscribe(
        self, handlers: Mapping[str, Callable[[Notification], Any]]
    ) -> Callable[[], None]:
        """Call ``handlers[name](notification)`` per event (names in
        :data:`crowdypy.replication.HANDLER_NAMES`); kept across reconnects. Returns the
        unsubscribe function. On a hot path read ``connection.batches()`` instead."""
        unknown = set(handlers) - HANDLER_NAMES
        if unknown:
            raise ValueError(f"unknown handler name(s): {', '.join(sorted(unknown))}")
        entry = dict(handlers)
        self._subscriptions.append(entry)

        def unsubscribe() -> None:
            if entry in self._subscriptions:
                self._subscriptions.remove(entry)

        return unsubscribe

    def _live(self) -> ReplicationConnection:
        connection = self._connection
        if connection is None:
            raise CrowdyReplicationError("call client.udp.connect() first", code="NotConnected")
        return connection

